import { ActionId } from '../../proto_utils/action_id';
import { AuraMetrics, SimResult, SimResultFilter } from '../../proto_utils/sim_result';
import { formatDeltaTextElem } from '../../utils.js';

import { ColumnSortType, MetricsTable } from './metrics_table';
import { ResultComponent, ResultComponentConfig, SimResultData } from './result_component';

export class AuraMetricsTable extends MetricsTable<AuraMetrics> {
	private readonly useDebuffs: boolean;

	constructor(config: ResultComponentConfig, useDebuffs: boolean) {
		if (useDebuffs) {
			config.rootCssClass = 'debuff-metrics-root';
		} else {
			config.rootCssClass = 'buff-metrics-root';
		}
		
		let lastSimResult: SimResultData | null = null;
		config.resultsEmitter.on((eventID, resultData) => {
			lastSimResult = resultData;
		});

		// Arrow function so we can cleanly access 'this.useDebuffs' inside
		const renderDiffCell = (metric: AuraMetrics, cellElem: HTMLElement, getValue: (m: AuraMetrics) => number, precision: number, isPercent: boolean = false, lowerIsBetter: boolean = false) => {
			const val = getValue(metric);
			cellElem.innerHTML = '';
			const baseSpan = document.createElement('span');
			baseSpan.textContent = val.toFixed(precision) + (isPercent ? '%' : '');

			if (lastSimResult && lastSimResult.referenceResult) {
				let refRawAuras: AuraMetrics[] = [];
				let curRawAuras: AuraMetrics[] = [];

				if (this.useDebuffs) {
					refRawAuras = lastSimResult.referenceResult.getDebuffMetrics(lastSimResult.filter);
					curRawAuras = lastSimResult.result.getDebuffMetrics(lastSimResult.filter);
				} else {
					const refPlayers = lastSimResult.referenceResult.getPlayers(lastSimResult.filter);
					const curPlayers = lastSimResult.result.getPlayers(lastSimResult.filter);
					
					if (refPlayers.length === 1 && curPlayers.length === 1) {
						const refPlayer = refPlayers[0];
						const curPlayer = curPlayers[0];

						if (metric.unit?.isPet) {
							const refPet = refPlayer.pets.find(p => p.name === metric.unit?.name);
							if (refPet) refRawAuras = refPet.auras;
							
							const curPet = curPlayer.pets.find(p => p.name === metric.unit?.name);
							if (curPet) curRawAuras = curPet.auras;
						} else {
							refRawAuras = refPlayer.auras;
							curRawAuras = curPlayer.auras;
						}
					}
				}

				if (refRawAuras.length > 0 && curRawAuras.length > 0) {
					const curGroups = AuraMetrics.groupById(curRawAuras);
					const matchingGroup = curGroups.find(g => g.some(a => a.actionId.equals(metric.actionId)));

					if (matchingGroup) {
						const groupProcs = matchingGroup.reduce((sum, a) => sum + a.averageProcs, 0);
						const isParent = Math.abs(metric.averageProcs - groupProcs) < 0.1;

						let refVal: number | null = null;

						if (isParent) {
							const refGroups = AuraMetrics.groupById(refRawAuras);
							const matchingRefGroup = refGroups.find(g => g.some(a => a.actionId.equals(metric.actionId)));
							if (matchingRefGroup) {
								const mergedRef = AuraMetrics.merge(matchingRefGroup, true, metric.unit?.petActionId || undefined);
								refVal = getValue(mergedRef);
							}
						} else {
							const refAura = refRawAuras.find(a => a.actionId.equals(metric.actionId));
							if (refAura) refVal = getValue(refAura);
						}

						if (refVal !== null && val !== refVal) {
							const deltaSpan = document.createElement('span');
							formatDeltaTextElem(deltaSpan, refVal, val, precision, lowerIsBetter, false, false);
							if (isPercent) deltaSpan.textContent += '%';
							
							// Using brackets and a physical non-breaking space (\u00A0) to prevent copy-paste squish
							deltaSpan.textContent = `[${deltaSpan.textContent}]\u00A0`;
							
							deltaSpan.style.marginRight = '4px';
							deltaSpan.style.fontSize = '0.8em';
							deltaSpan.style.opacity = '0.85'; 
							deltaSpan.style.whiteSpace = 'nowrap'; 
							
							cellElem.appendChild(deltaSpan);
						}
					}
				}
			}
			cellElem.appendChild(baseSpan);
		};
		
		super(config, [
			MetricsTable.nameCellConfig((metric: AuraMetrics) => {
				return {
					name: metric.name,
					actionId: metric.actionId,
				};
			}),
			{
				name: 'Procs',
				tooltip: 'Procs',
				getValue: (metric: AuraMetrics) => metric.averageProcs,
				//getDisplayString: (metric: AuraMetrics) => metric.averageProcs.toFixed(2),
				fillCell: (metric: AuraMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.averageProcs, 2),
			},
			{
				name: 'PPM',
				tooltip: 'Procs Per Minute',
				getValue: (metric: AuraMetrics) => metric.ppm,
				//getDisplayString: (metric: AuraMetrics) => metric.ppm.toFixed(2),
				fillCell: (metric: AuraMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.ppm, 2),
			},
			{
				name: 'Uptime',
				tooltip: 'Uptime / Encounter Duration',
				sort: ColumnSortType.Descending,
				getValue: (metric: AuraMetrics) => metric.uptimePercent,
				//getDisplayString: (metric: AuraMetrics) => metric.uptimePercent.toFixed(2) + '%',
				fillCell: (metric: AuraMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.uptimePercent, 2, true),
			},
		]);
		this.useDebuffs = useDebuffs;
	}

	getGroupedMetrics(resultData: SimResultData): Array<Array<AuraMetrics>> {
		if (this.useDebuffs) {
			return AuraMetrics.groupById(resultData.result.getDebuffMetrics(resultData.filter));
		} else {
			const players = resultData.result.getPlayers(resultData.filter);
			if (players.length != 1) {
				return [];
			}
			const player = players[0];

			const auras = player.auras;
			const actionGroups = AuraMetrics.groupById(auras);
			const petGroups = player.pets.map(pet => pet.auras);

			return actionGroups.concat(petGroups);
		}
	}

	mergeMetrics(metrics: Array<AuraMetrics>): AuraMetrics {
		return AuraMetrics.merge(metrics, true, metrics[0].unit?.petActionId || undefined);
	}

	shouldCollapse(metric: AuraMetrics): boolean {
		return !metric.unit?.isPet;
	}
}
